#include "../src/AlphaSimulation.h"
#include <iostream>
#include <stdexcept>
using namespace alpha;int checks=0;
void check(bool ok,const char* name){if(!ok)throw std::runtime_error(name);++checks;std::cout<<"PASS "<<name<<std::endl;}
void advance(World& w,float s){for(int i=0;i<int(s*20)&&!w.result;++i)w.step(.05f);}
int count(World& w,Kind k,int team){int n=0;for(auto& e:w.entities)if(e.hp>0&&e.kind==k&&e.team==team)++n;return n;}
int main(){try{
 {World w;w.reset();w.startGuided();check(w.guided&&w.chapter==0,"prologue begins with farm objective");check(!w.train(1,Kind::Worker),"no additional player units before completed farm");check(!w.unavailable(Kind::Barracks).empty(),"barracks locked before first farm");check(!w.researchIssue(1,Research::Town2).empty(),"upgrades locked during first lessons");advance(w,400);check(count(w,Kind::Soldier,1)==3,"no free enemy waves in early lessons");bool attack=false;for(auto& e:w.entities)if(e.team==1&&e.order==Order::Attack)attack=true;check(!attack,"guards do not attack base on a timer during early lessons");}
 {World w;w.reset();w.startGuided();w.gold=w.wood=5000;check(w.build(7,{430,800},Kind::Farm),"guided farm construction starts");int farm=w.entities.back().id;check(w.busy(*w.get(7)),"worker committed to foundation");int gold=w.gold;check(!w.build(7,{600,700},Kind::Farm)&&w.gold==gold,"busy worker cannot start second foundation");w.move(*w.get(7),{900,750});w.gather(*w.get(7),3);w.attack(*w.get(7),13);w.repair(*w.get(7),1);check(w.busy(*w.get(7))&&w.get(7)->target==farm,"busy worker rejects move gather attack and repair");advance(w,20);check(w.get(farm)->build==0&&!w.busy(*w.get(7))&&w.chapter==1,"completed farm releases worker and unlocks barracks");check(w.build(7,{650,750},Kind::Barracks),"guided barracks starts");int barracks=w.entities.back().id;advance(w,25);check(w.get(barracks)->build==0&&w.chapter==2,"completed barracks unlocks training lesson");check(w.train(barracks,Kind::Soldier),"guided soldier training paid");advance(w,8);check(w.chapter==3,"three soldiers unlock economy technologies");check(w.unavailable(Kind::Forge).empty(),"forge unlocked by army objective");check(w.researchIssue(1,Research::Town3).find("Esplora")!=std::string::npos,"advanced town waits for scouting objective");w.move(*w.get(11),{1150,750});advance(w,20);check(w.chapter==4&&w.exploredAt({1250,750}),"scouting actually advances final objective");advance(w,180);check(w.has(1,Kind::Farm)&&w.has(1,Kind::Barracks),"enemy builds completed farm and barracks through workers");check(w.enemyGold>=0&&w.enemyWood>=0&&w.population(1)<=w.capacity(1),"enemy respects funds and supply");}
 {World w;w.reset();w.raidsEnabled=false;w.gold=w.wood=1000;check(w.build(7,{650,750},Kind::Farm),"foundation for orphan test");int site=w.entities.back().id;w.get(7)->hp=0;float remaining=w.get(site)->build;advance(w,10);check(w.get(site)->build==remaining,"construction stops when builder dies");w.repair(*w.get(8),site);check(w.busy(*w.get(8)),"another worker resumes abandoned foundation");advance(w,20);check(w.get(site)->build==0&&!w.busy(*w.get(8)),"replacement worker completes and becomes free");}
 {World w;w.reset();w.raidsEnabled=false;int b=w.add(Kind::Barracks,1,{1800,750});w.enemyGold=0;int gold=w.gold;check(!w.train(b,Kind::Soldier)&&w.gold==gold,"enemy cannot use player funds or train for free");w.enemyGold=1000;while(w.population(1)<w.capacity(1))w.add(Kind::Soldier,1,{1900,700});check(!w.train(b,Kind::Soldier),"enemy cannot train above population cap");int f=w.add(Kind::Farm,1,{1800,850});check(w.train(b,Kind::Soldier)&&w.enemyGold==920,"enemy farm permits paid training");check(w.cancel(b)&&w.enemyGold==1000&&w.gold==gold,"enemy cancellation refunds own funds");w.get(f)->hp=0;check(!w.train(b,Kind::Soldier),"destroyed enemy farm blocks further training");int worker=w.add(Kind::Worker,1,{1980,620});int before=w.enemyGold;w.gather(*w.get(worker),5);advance(w,35);check(w.enemyGold>before&&w.gold==gold,"enemy gathers and credits its own resources");}
 {World w;w.reset();w.startGuided();w.chapter=4;w.raidsEnabled=false;int barracks=w.add(Kind::Barracks,1,{1800,750});w.enemyGold=1000;check(!w.train(barracks,Kind::Soldier),"same no-farm rule blocks enemy even below capacity");w.add(Kind::Farm,1,{1800,850});check(w.train(barracks,Kind::Soldier),"completed farm unlocks enemy production under same rules");int before=count(w,Kind::Soldier,1);for(auto& e:w.entities)if(e.team==1&&e.kind==Kind::Farm)e.hp=0;advance(w,9);check(count(w,Kind::Soldier,1)==before&&w.get(barracks)->production>0,"lost farm pauses queued enemy production without spawning over cap");for(auto& e:w.entities)if(e.team==1&&e.kind==Kind::Farm)e.hp=e.maxHp;advance(w,1);check(count(w,Kind::Soldier,1)==before+1,"queued production resumes when farm capacity restored");}
 std::cout<<"SUCCESS "<<checks<<" progression and shared economy checks"<<std::endl;return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}}
